<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Student','Admin']); render_header('My Subjects'); ?><div class="page-title"><div><h1>My Subjects</h1><p>Subjects matching your assigned course and year level.</p></div></div><div class="panel"><table class="table"><thead><tr><th>Code</th><th>Title</th><th>Units</th><th>Year Level</th></tr></thead><tbody><?php foreach(rows('SELECT sub.* FROM subjects sub WHERE EXISTS (SELECT 1 FROM students s WHERE '.student_scope_sql().' AND s.course_id=sub.course_id AND s.year_level=sub.year_level) ORDER BY sub.code') as $s): ?><tr><td><?= e($s['code']) ?></td><td><?= e($s['title']) ?></td><td><?= e($s['units']) ?></td><td><?= e($s['year_level']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php render_footer(); ?>
